"""Reusable conversions for Meridian CRM legacy storage conventions."""

from __future__ import annotations

from datetime import date
from decimal import Decimal, ROUND_HALF_UP
from typing import Any

__all__ = ["to_iso", "from_iso", "yn", "to_minor_units"]

_LEGACY_NULL_DATE = "00000000"


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD, preserving null semantics."""
    if yyyymmdd is None or yyyymmdd == "" or yyyymmdd == _LEGACY_NULL_DATE:
        return None

    if len(yyyymmdd) != 8 or not yyyymmdd.isdigit():
        raise ValueError(f"invalid legacy date: {yyyymmdd!r}")

    return date.fromisoformat(
        f"{yyyymmdd[:4]}-{yyyymmdd[4:6]}-{yyyymmdd[6:8]}"
    ).isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to a legacy YYYYMMDD date."""
    if iso is None or iso == "":
        return _LEGACY_NULL_DATE

    return date.fromisoformat(iso).strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert legacy CHAR(1) Y/N values, where blank means N."""
    return char == "Y"


def to_minor_units(amount: Any, currency: str | None) -> int:
    """Convert a legacy decimal amount to currency minor units using half-up rounding."""
    if amount is None or (isinstance(amount, str) and amount.strip() == ""):
        return 0

    currency_code = "USD" if currency is None or currency.strip() == "" else currency
    exponent = 0 if currency_code == "JPY" else 2

    decimal_amount = Decimal(str(amount))
    unit = Decimal(1).scaleb(-exponent)
    rounded = decimal_amount.quantize(unit, rounding=ROUND_HALF_UP)
    return int(rounded.scaleb(exponent))
